package com.tracksphere.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="geofences") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Geofence { @Id private UUID id; @Column(nullable=false,length=120) private String name; @Column(nullable=false) private double latitude; @Column(nullable=false) private double longitude; @Column(name="radius_meters",nullable=false) private double radiusMeters; @Column(nullable=false) private boolean active=true; @Column(name="created_at",nullable=false) private Instant createdAt; public Geofence(String name,double latitude,double longitude,double radiusMeters){id=UUID.randomUUID();this.name=name;this.latitude=latitude;this.longitude=longitude;this.radiusMeters=radiusMeters;createdAt=Instant.now();} }
